const errors = [];
const o = (b && typeof b === 'object' && !Array.isArray(b)) ? b : {};
if (o !== b) errors.push('body must be a JSON object');
const idOf = (v) => (typeof v === 'number' && Number.isFinite(v) ? String(v) : (typeof v === 'string' ? v.trim() : ''));
const order_id = idOf(o.order_id);
if (!/^[A-Za-z0-9_-]{1,40}$/.test(order_id)) errors.push('order_id is required (1-40 letters, digits, - or _)');
let order_number = '';
if (o.order_number !== undefined && o.order_number !== null && o.order_number !== '') {
  order_number = idOf(o.order_number);
  if (!/^[A-Za-z0-9_#-]{1,40}$/.test(order_number)) { errors.push('order_number invalid'); order_number = ''; }
}
const buyer_first_name = clean(o.buyer_first_name, 60);
if (!buyer_first_name) errors.push('buyer_first_name is required (max 60)');
const items = [];
if (!Array.isArray(o.items) || o.items.length < 1 || o.items.length > 50) errors.push('items must be an array of 1-50');
else o.items.forEach((it, i) => {
  const title = clean(it && it.title, 200);
  const qty = it && it.qty;
  const price = it && it.price;
  if (!title) errors.push('items[' + i + '].title is required');
  if (!Number.isInteger(qty) || qty < 1 || qty > 999) errors.push('items[' + i + '].qty must be an integer 1-999');
  if (price !== undefined && price !== null && !(typeof price === 'number' && Number.isFinite(price) && price >= 0 && price <= 100000)) errors.push('items[' + i + '].price must be a number 0-100000');
  items.push({ title, qty, price: typeof price === 'number' ? price : null });
});
const total = o.total;
if (!(typeof total === 'number' && Number.isFinite(total) && total >= 0 && total <= 1000000)) errors.push('total must be a number 0-1000000');
const currency = typeof o.currency === 'string' ? o.currency.trim().toUpperCase() : '';
if (!/^[A-Z]{3}$/.test(currency)) errors.push('currency must be a 3-letter code');
const day = (v, label, required) => {
  if (v === undefined || v === null || v === '') { if (required) errors.push(label + ' is required'); return ''; }
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}([T ][\d:.]+(Z|[+-]\d{2}:?\d{2})?)?$/.test(v.trim()) || isNaN(Date.parse(v.trim().slice(0, 10) + 'T00:00:00Z'))) { errors.push(label + ' must be a YYYY-MM-DD date'); return ''; }
  return v.trim().slice(0, 10);
};
const order_date = day(o.order_date, 'order_date', true);
const ship_by = day(o.ship_by, 'ship_by', false);
let items_summary = items.map(it => it.qty + ' x ' + it.title).join('; ');
if (items_summary.length > 1900) items_summary = items_summary.slice(0, 1897) + '...';
return [{ json: { valid: errors.length === 0, errors, order_id, order_number, buyer_first_name, items, items_summary, total, currency, order_date, ship_by } }];

const v = $('Validate Order').first().json;
const text = (x) => !x ? '' : (x.title || x.rich_text || []).map(t => t.plain_text).join('');
let exists = false;
for (const it of $('Notion Find Order').all()) {
  const p = it.json && it.json.properties;
  if (p && text(p['Order ID']) === v.order_id) { exists = true; break; }
}
return [{ json: { exists, order_id: v.order_id } }];

const b = $input.first().json.body;
const clean = (v, max) => (typeof v === 'string' ? v.replace(/[\u0000-\u001F\u007F-\u009F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max) : '');
const errors = [];
const o = (b && typeof b === 'object' && !Array.isArray(b)) ? b : {};
if (o !== b) errors.push('body must be a JSON object');
const idOf = (v) => (typeof v === 'number' && Number.isFinite(v) ? String(v) : (typeof v === 'string' ? v.trim() : ''));
const order_id = idOf(o.order_id);
if (!/^[A-Za-z0-9_-]{1,40}$/.test(order_id)) errors.push('order_id is required (1-40 letters, digits, - or _)');
const tracking_number = clean(o.tracking_number, 60);
if (!/^[A-Za-z0-9 -]{4,60}$/.test(tracking_number)) errors.push('tracking_number is required (4-60 letters, digits, space or -)');
const carrier = clean(o.carrier, 40);
if (!/^[A-Za-z0-9 .&-]{2,40}$/.test(carrier)) errors.push('carrier is required (2-40 characters)');
let shipped_at = '';
if (o.shipped_at !== undefined && o.shipped_at !== null && o.shipped_at !== '') {
  const s = typeof o.shipped_at === 'string' ? o.shipped_at.trim() : '';
  if (!/^\d{4}-\d{2}-\d{2}([T ][\d:.]+(Z|[+-]\d{2}:?\d{2})?)?$/.test(s) || isNaN(Date.parse(s.slice(0, 10) + 'T00:00:00Z'))) errors.push('shipped_at must be a YYYY-MM-DD date');
  else shipped_at = s.slice(0, 10);
}
if (!shipped_at && errors.length === 0) shipped_at = new Date().toISOString().slice(0, 10);
return [{ json: { valid: errors.length === 0, errors, order_id, tracking_number, carrier, shipped_at } }];

const v = $('Validate Shipped').first().json;
const text = (x) => !x ? '' : (x.title || x.rich_text || []).map(t => t.plain_text).join('');
let row = null;
for (const it of $('Notion Find Order B').all()) {
  const p = it.json && it.json.properties;
  if (!p || text(p['Order ID']) !== v.order_id) continue;
  row = { found: true, page_id: it.json.id, order_id: v.order_id, order_number: text(p['Order Number']), buyer_first_name: text(p['Buyer First Name']), items_summary: text(p['Items Summary']), status: (p['Status'] && p['Status'].select && p['Status'].select.name) || '', tracking_number: v.tracking_number, carrier: v.carrier, shipped_at: v.shipped_at };
  break;
}
return [{ json: row || { found: false, order_id: v.order_id } }];

const j = $input.first().json;
const status = j.status || '';
let allowed = false, reason = '';
if (status === 'New' || status === 'Packed') allowed = true;
else if (status === 'Shipped') reason = 'Order is already Shipped; not shipping it again.';
else reason = 'Order status "' + status + '" cannot be shipped; it must be New or Packed.';
return [{ json: Object.assign({}, j, { allowed, guard_reason: reason }) }];

// Uses ONLY data stored on the Etsy Orders row (plus the carrier and tracking number just received).
// No delivery dates, no addresses, no promises beyond what is in the row.
const r = $('Guard').first().json;
const first = r.buyer_first_name || 'there';
const lines = [];
lines.push('Hi ' + first + ',');
lines.push('');
lines.push('Good news, your order has shipped' + (r.carrier ? ' with ' + r.carrier : '') + '.');
if (r.items_summary) lines.push('Items: ' + r.items_summary);
if (r.tracking_number) lines.push('Tracking number: ' + r.tracking_number);
lines.push('');
lines.push('Thank you so much for supporting TheLuminousFairy. If anything is not right with your order, just send us a message and we will help.');
lines.push('');
lines.push('TheLuminousFairy');
const draft = lines.join('\n');
const title = 'Shipping confirmation: ' + (r.order_number || r.order_id);
return [{ json: { title, draft, order_id: r.order_id, page_id: r.page_id } }];

const p = $('Build Draft').first().json;
const TITLE = p.title, AGENT = 'Etsy', TYPE = 'Reply', DRAFT = p.draft, RELATED = 'Etsy order ' + p.order_id;

// Notion rich-text items hold at most 2000 chars, so Draft is written as several rich_text items of <=1900 chars.
// Concatenating the items' plain_text (what QA does) gives back the exact original text. Nothing is truncated.
const MAX = 1900;
const chunk = (s) => {
  const out = [];
  let i = 0;
  while (i < s.length) {
    let end = Math.min(i + MAX, s.length);
    if (end < s.length) { const c = s.charCodeAt(end - 1); if (c >= 0xD800 && c <= 0xDBFF) end -= 1; } // do not split a surrogate pair
    out.push(s.slice(i, end));
    i = end;
  }
  return out;
};
const rich = (s) => chunk(String(s)).map(c => ({ type: 'text', text: { content: c } }));
const body = {
  parent: { database_id: 'a807f4c25dfe4ce388626726b7d99f6d' },
  properties: {
    'Title': { title: [{ type: 'text', text: { content: String(TITLE).slice(0, 150) } }] },
    'Agent': { select: { name: AGENT } },
    'Type': { select: { name: TYPE } },
    'Draft': { rich_text: rich(DRAFT) },
    'Status': { select: { name: 'Awaiting Approval' } },
    'QA Result': { select: { name: 'Not checked' } },
    'Related Job': { rich_text: rich(String(RELATED).slice(0, 1900)) }
  }
};
return [{ json: { notionBody: body } }];
